    <script src="https://cdnjs.cloudflare.com/ajax/libs/sigma.js/1.2.1/plugins/sigma.parsers.json.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/sigma.js/1.2.1/plugins/sigma.layout.forceAtlas2.min.js"></script>
    <style>
        body { margin: 0; background: #000; color: #fff; font-family: 'Segoe UI', sans-serif; overflow: hidden; }
        #container { width: 100vw; height: 100vh; background: #000; }
        #ui { position: absolute; top: 20px; left: 20px; z-index: 10; pointer-events: none; background: rgba(0,0,0,0.9); padding: 20px; border-left: 4px solid #ff00ff; border-radius: 0 10px 10px 0; }
        h1 { margin: 0; font-size: 26px; font-weight: 300; letter-spacing: 3px; color: #ff00ff; text-shadow: 0 0 15px #ff00ff; }
        p { font-size: 13px; color: #888; margin: 8px 0; }
        .stat { color: #fff; font-weight: 600; }
    </style>
</head>
<body>
    <div id="ui">
        <h1>WikiSfera Explorer 🌌</h1>
        <p>Tryb: <span class="stat">Deep Space (High Density Spacing)</span></p>
        <p>Interakcja: <span class="stat">Hover to Highlight Connections</span></p>
    </div>
    <div id="container"></div>

    <script>
        sigma.parsers.json('map_data.json', {
            container: 'container',
            settings: {
                defaultNodeColor: '#00f2ff',
                edgeColor: 'default',
                defaultEdgeColor: 'rgba(255, 255, 255, 0.01)',
                labelThreshold: 5,
                labelSize: 'fixed',
                defaultLabelSize: 11,
                defaultLabelColor: '#fff',
                minNodeSize: 1,
                maxNodeSize: 40,
                scalingMode: 'outside',
                hideEdgesOnMove: true,
                zoomMin: 0.0001,
                zoomMax: 2
            }
        }, function(s) {
            // Zapisujemy oryginalne kolory
            s.graph.nodes().forEach(function(n) {
                const ratio = n.size / 40;
                if (ratio > 0.6) n.color = '#ff0055';
                else if (ratio > 0.3) n.color = '#00f2ff';
                else n.color = '#004466';
                n.originalColor = n.color;
            });
            s.graph.edges().forEach(function(e) {
                e.originalColor = 'rgba(255, 255, 255, 0.01)';
            });

            // Fizyka z ogromnymi odstępami
            s.startForceAtlas2({
                worker: true,
                barnesHutOptimize: true,
                gravity: 0.05,
                scalingRatio: 1200, // Ekstremalne rozpychanie
                strongGravityMode: false,
                outboundAttractionDistribution: true,
                linLogMode: true,
                adjustSizes: true
            });

            // Logika podświetlania
            s.bind('overNode', function(e) {
                var nodeId = e.data.node.id;
                var neighbors = {};

                // Znajdź sąsiadów
                s.graph.edges().forEach(function(edge) {
                    if (edge.source === nodeId || edge.target === nodeId) {
                        neighbors[edge.source] = true;
                        neighbors[edge.target] = true;
                        edge.color = '#fff';
                        edge.size = 2;
                    } else {
                        edge.color = 'rgba(0,0,0,0)';
                    }
                });

                s.graph.nodes().forEach(function(node) {
                    if (neighbors[node.id] || node.id === nodeId) {
                        node.color = node.originalColor;
                    } else {
                        node.color = '#111';
                    }
                });
                s.refresh();
            });

            s.bind('outNode', function() {
                s.graph.nodes().forEach(function(node) {
                    node.color = node.originalColor;
                });
                s.graph.edges().forEach(function(edge) {
                    edge.color = edge.originalColor;
                    edge.size = 1;
                });
                s.refresh();
            });

            setTimeout(function() {
                // s.stopForceAtlas2(); // Opcjonalnie zatrzymaj po ułożeniu
            }, 30000);
        });
    </script>
</body>
</html>

